// James's photoreal 3D head (GAGAvatar) rendered as a CAMERA ORBIT: one source photo,
// reconstructed to a 3D Gaussian head, camera azimuth swept +/-30 deg. Autoplay loop =
// continuous pan; drag left/right to rotate manually (scrubs the orbit). The .ply itself
// holds 32-dim neural features (not RGB/SH) so it can't go in a generic splat viewer -
// this is the head's own renderer output, the faithful way to show the 3D in-canvas.
import * as React from 'react';
const ORBIT_MP4 = "data:video/mp4;base64,";
export default function OrbitViewer() {
  const vid = React.useRef(null);
  const wrap = React.useRef(null);
  const [drag, setDrag] = React.useState(false);
  const scrub = (clientX) => {
    const v = vid.current, w = wrap.current; if (!v || !w || !v.duration) return;
    const r = w.getBoundingClientRect();
    const f = Math.max(0, Math.min(1, (clientX - r.left) / r.width));
    v.currentTime = f * v.duration;
  };
  const down = (e) => { const v = vid.current; if (v) v.pause(); setDrag(true); scrub(e.clientX); e.currentTarget.setPointerCapture?.(e.pointerId); };
  const move = (e) => { if (drag) scrub(e.clientX); };
  const up = () => { setDrag(false); const v = vid.current; if (v) v.play().catch(()=>{}); };
  return (
    <div style={{ height: '100%', boxSizing: 'border-box', background: '#0f0f12', color: '#f3f4f6', fontFamily: 'system-ui, sans-serif', borderRadius: 10, padding: 14, display: 'flex', flexDirection: 'column', gap: 10 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
        <span style={{ fontSize: 15 }}>✨</span>
        <span style={{ fontSize: 13, fontWeight: 700 }}>James · 3D head, rotating</span>
        <span style={{ marginLeft: 'auto', fontSize: 10, color: '#34d399', fontWeight: 700, border: '1px solid #34d39955', borderRadius: 12, padding: '2px 8px' }}>1 photo · live 3D</span>
      </div>
      <div ref={wrap} onPointerDown={down} onPointerMove={move} onPointerUp={up} onPointerLeave={()=>drag&&up()}
           style={{ position: 'relative', flex: 1, minHeight: 0, borderRadius: 10, overflow: 'hidden', border: '1px solid #26262e', background: '#000', cursor: drag ? 'grabbing' : 'grab' }}>
        <video ref={vid} src={ORBIT_MP4} autoPlay loop muted playsInline
               style={{ width: '100%', height: '100%', objectFit: 'contain', display: 'block', pointerEvents: 'none' }} />
        <div style={{ position: 'absolute', bottom: 8, left: 0, right: 0, textAlign: 'center', fontSize: 10.5, color: '#cbd5e1', textShadow: '0 1px 3px #000', pointerEvents: 'none' }}>
          ← drag to rotate → · auto-spins when released
        </div>
      </div>
      <div style={{ fontSize: 10.5, color: '#8b8b96', lineHeight: 1.45 }}>
        GAGAvatar feed-forward reconstruction, camera azimuth ±30°. Same identity locked across every angle · this is the 3D, not a 2D warp.
      </div>
    </div>
  );
}
